                    artifactId, contractId, Sql.ts(clock.instant()));
            return true;
        } catch (DuplicateKeyException e) {
            return false;
        }
    }

    public void releaseArtifact(Long contractId) {
        jdbc.update("DELETE FROM artifact_active_loan WHERE contract_id = ?", contractId);
