/**
 * 进入“待双方复核”需要同时满足：
 * 1) 异常仍处于 OPEN/URGENT；2) 保护工单已完成处置确认；3) 最新读数（按采样时刻归位）回到区间。
 * 任一不满足则维持现状；处置未确认时 24h 时限仍会继续生效。
 */
private void tryEnterAwaitReview(ShowcasePo showcase) {
